 31→/** Thrown when a bin operation is attempted before loadBin() has been called. */
 32→export class BinNotLoadedError extends Error {
 33→  constructor() {
 34→    super('Bin not loaded');
 35→    this.name = 'BinNotLoadedError';
 36→  }
 37→}
 38→
 39→export class CipherBoxClient {
 40→  private config: CipherBoxClientConfig;
 41→  private ctx: SdkContext;
 42→  private emitter: SdkEventEmitter;
 43→  private folderTree: FolderTree;
 44→  private keyCache: KeyCache;
 45→  private binState: BinState | null = null;
 46→  /** BYO-IPFS external pinning provider (null when mode is 'cipherbox') */
 47→  private externalProvider: PinningProvider | null = null;
 48→  /** Internal copies of key material — zeroed on destroy() without affecting caller buffers */
 49→  private internalVaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 50→  private internalRootFolderKey: Uint8Array;
 51→
 52→  constructor(config: CipherBoxClientConfig) {
 53→    // Defensive copy of key material so destroy() only zeroes our copies
 54→    this.internalVaultKeypair = {
 55→      publicKey: new Uint8Array(config.vaultKeypair.publicKey),
 56→      privateKey: new Uint8Array(config.vaultKeypair.privateKey),
 57→    };
 58→    this.internalRootFolderKey = new Uint8Array(config.rootFolderKey);
 59→    this.config = {
 60→      ...config,
 61→      vaultKeypair: this.internalVaultKeypair,
 62→      rootFolderKey: this.internalRootFolderKey,
 63→    };
 64→    const axiosInstance =
 65→      config.axiosInstance ??
 66→      createAxiosInstance({
 67→        baseUrl: config.apiUrl,
 68→        getAccessToken: config.getAccessToken,
 69→        defaultHeaders: config.defaultHeaders,
 70→      });
 71→    this.ctx = {
 72→      apiUrl: config.apiUrl,
 73→      getAccessToken: config.getAccessToken,
 74→      axiosInstance,
 75→    };
 76→    this.emitter = new SdkEventEmitter();
 77→    this.folderTree = new FolderTree();
 78→    this.keyCache = new KeyCache();
 79→
 80→    // Initialize BYO pinning provider if configured
 81→    if (config.pinningConfig?.mode !== 'cipherbox' && config.pinningConfig?.externalProvider) {
 82→      const ext = config.pinningConfig.externalProvider;
 83→      if (ext.protocol === 'kubo') {
 84→        this.externalProvider = new sdkCore.KuboProvider(ext.endpoint, ext.authToken);
 85→      } else if (ext.protocol === 'pinata') {
 86→        this.externalProvider = new sdkCore.PinataProvider(ext.endpoint, ext.authToken);
 87→      } else {
 88→        this.externalProvider = new sdkCore.PsaProvider(ext.endpoint, ext.authToken);
 89→      }
 90→    }
 91→  }
 92→
 93→  // ---- Event subscription ----
 94→
 95→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 96→  on(handler: SdkEventHandler): () => void {
 97→    return this.emitter.on(handler);
 98→  }
 99→
100→  /** Unsubscribe a previously registered handler. */

  1→import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
  2→import { ConfigService } from '@nestjs/config';
  3→import { MetricsService } from '../metrics/metrics.service';
  4→
  5→/** Typed error for non-retryable HTTP responses from the delegated routing API. */
  6→class DelegatedRoutingHttpError extends Error {
  7→  constructor(public readonly status: number) {
  8→    super(`Delegated routing returned ${status}`);
  9→    this.name = 'DelegatedRoutingHttpError';
 10→  }
 11→}
 12→
 13→@Injectable()
 14→export class DelegatedRoutingClient {
 15→  private readonly logger = new Logger(DelegatedRoutingClient.name);
 16→  private readonly primaryUrl: string;
 17→  private readonly fallbackUrl: string | null;
 18→  private readonly maxRetries = 3;
 19→  private readonly baseDelayMs = 1000;
 20→  private readonly maxRetryDelayMs = 30_000;
 21→  private readonly requestTimeoutMs = 10_000;
 22→
 23→  constructor(
 24→    private readonly configService: ConfigService,
 25→    private readonly metricsService: MetricsService
 26→  ) {
 27→    this.primaryUrl = this.configService.get<string>(
 28→      'DELEGATED_ROUTING_URL',
 29→      'https://delegated-ipfs.dev'
 30→    );
 31→    const fallback = this.configService.get<string>('DELEGATED_ROUTING_FALLBACK_URL', '');
 32→    this.fallbackUrl = fallback || null;
 33→
 34→    if (this.fallbackUrl) {
 35→      this.logger.log(
 36→        `Delegated routing: primary=${this.primaryUrl}, fallback=${this.fallbackUrl}`
 37→      );
 38→    } else {
 39→      this.logger.log(`Delegated routing: ${this.primaryUrl} (no fallback configured)`);
 40→    }
 41→  }
 42→
 43→  /**
 44→   * Publish an IPNS record via the delegated routing PUT API.
 45→   * Tries primary backend first, falls back to fallback URL if configured.
 46→   * Throws HttpException (BAD_GATEWAY) on persistent failures across all backends.
 47→   */
 48→  async publish(ipnsName: string, recordBytes: Uint8Array): Promise<void> {
 49→    const encodedName = encodeURIComponent(ipnsName);
 50→    const path = `/routing/v1/ipns/${encodedName}`;
 51→
 52→    try {
 53→      await this.executePublish(this.primaryUrl + path, recordBytes, ipnsName, 'primary');
 54→      return;
 55→    } catch (primaryError) {
 56→      if (!this.fallbackUrl) throw primaryError;
 57→
 58→      this.logger.warn(
 59→        `Primary routing failed for publish ${ipnsName}, trying fallback: ${
 60→          primaryError instanceof Error ? primaryError.message : String(primaryError)
 61→        }`
 62→      );
 63→      this.metricsService.delegatedRoutingFallbacks.inc({ operation: 'publish' });
 64→    }
 65→
 66→    await this.executePublish(this.fallbackUrl + path, recordBytes, ipnsName, 'fallback');
 67→  }
 68→
 69→  /**
 70→   * Resolve an IPNS name via the delegated routing GET API.
 71→   * Tries primary backend first, falls back to fallback URL if configured.
 72→   * Returns the raw record bytes, or null if the IPNS name is not found (404).
 73→   * Throws HttpException (BAD_GATEWAY) on persistent failures across all backends.
 74→   */
 75→  async resolve(ipnsName: string): Promise<Uint8Array | null> {
 76→    const encodedName = encodeURIComponent(ipnsName);
 77→    const path = `/routing/v1/ipns/${encodedName}`;
 78→
 79→    try {
 80→      return await this.executeResolve(this.primaryUrl + path, ipnsName, 'primary');
 81→    } catch (primaryError) {
 82→      if (!this.fallbackUrl) throw primaryError;
 83→
 84→      this.logger.warn(
 85→        `Primary routing failed for resolve ${ipnsName}, trying fallback: ${
 86→          primaryError instanceof Error ? primaryError.message : String(primaryError)
 87→        }`
 88→      );
 89→      this.metricsService.delegatedRoutingFallbacks.inc({ operation: 'resolve' });
 90→    }
 91→
 92→    return this.executeResolve(this.fallbackUrl + path, ipnsName, 'fallback');
 93→  }
 94→
 95→  private async executePublish(
 96→    url: string,
 97→    recordBytes: Uint8Array,
 98→    ipnsName: string,
 99→    backend: 'primary' | 'fallback'
100→  ): Promise<void> {
101→    let lastError: Error | null = null;
102→
103→    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
104→      try {
105→        const { ok, status, retryAfter, errorText } = await this.fetchWithTimeout(
106→          url,
107→          {
108→            method: 'PUT',
109→            headers: {
110→              'Content-Type': 'application/vnd.ipfs.ipns-record',
111→            },
112→            body: recordBytes as unknown as BodyInit,
113→          },
114→          async (response) => ({
115→            ok: response.ok,
116→            status: response.status,
117→            retryAfter: response.headers.get('Retry-After'),
118→            errorText: !response.ok && response.status !== 429 ? await response.text() : '',
119→          })
120→        );

 1→import type { PinningProvider, PinResult, PinStatus } from './types';
 2→
 3→/** Timeout for all Kubo RPC requests (30 seconds) */
 4→const REQUEST_TIMEOUT_MS = 30_000;
 5→
 6→/**
 7→ * PinningProvider implementation for Kubo RPC API (/api/v0/*).
 8→ *
 9→ * Talks directly to a Kubo node's HTTP API. Suitable for self-hosted
10→ * Kubo nodes or any IPFS node exposing the Kubo-compatible RPC interface.
11→ */
12→export class KuboProvider implements PinningProvider {
13→  private readonly endpoint: string;
14→  private readonly authToken?: string;
15→
16→  constructor(endpoint: string, authToken?: string) {
17→    // Normalize: strip trailing slash
18→    this.endpoint = endpoint.replace(/\/+$/, '');
19→    this.authToken = authToken;
20→  }
21→
22→  /**
23→   * Upload and pin data to the Kubo node.
24→   * Uses /api/v0/add with pin=true and cid-version=1 for CIDv1.
25→   */
26→  async pin(data: Uint8Array, _name?: string): Promise<PinResult> {
27→    const url = `${this.endpoint}/api/v0/add?pin=true&cid-version=1`;
28→    const formData = new FormData();
29→    // Pass typed array directly to Blob (never use .buffer to avoid offset issues)
30→    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
31→    formData.append('file', blob);
32→
33→    const response = await fetch(url, {
34→      method: 'POST',
35→      body: formData,
36→      headers: this.buildHeaders(),
37→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
38→    });
39→
40→    if (!response.ok) {
41→      const errorText = await response.text();
42→      throw new Error(`Kubo add failed: ${response.status} - ${errorText}`);
43→    }
44→
45→    // Kubo returns ndjson; for a single file, parse the first (only) line
46→    const text = await response.text();
47→    const result = JSON.parse(text) as { Hash: string; Size: string };
48→    return {
49→      cid: result.Hash,
50→      size: parseInt(result.Size, 10),
51→    };
52→  }
53→
54→  /**
55→   * Remove a pin by CID.
56→   * Ignores "not pinned" errors for idempotency.
57→   */
58→  async unpin(cid: string): Promise<void> {
59→    const url = `${this.endpoint}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}`;
60→
61→    const response = await fetch(url, {
62→      method: 'POST',
63→      headers: this.buildHeaders(),
64→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
65→    });
66→
67→    if (!response.ok) {
68→      const errorText = await response.text();
69→      // "not pinned" means already unpinned -- treat as success (idempotent)
70→      if (errorText.toLowerCase().includes('not pinned')) {
71→        return;
72→      }
